<script setup lang="ts">
import { qtrc, useLanguage } from '../../../i18n'
import ChordNumber from './ChordNumber.vue'
import { ICON_CODES } from '../../../actions/uiactiondata'
import { StyledXYControllerWithReset } from './controls.vue'
import { PointF } from '../../../../src/framework/draw/types/geometry'
import { allTextStyles, textStyle, TextStylePropertyType } from '../../../../src/engraving/style/textstyle'
import { TConv } from '../../../../src/engraving/types/typesconv'
import { TextStyleType } from '../../../../src/engraving/types/types'
import {
  GroupBox,
  RadioButtonSelectorWithReset,
  StyleSpinboxWithReset,
  StyleToggle,
  type NotationStyleLike,
} from './controls.vue'

const props = defineProps<{
  score?: any
  style: NotationStyleLike
  goToTextStylePage?: (codeOrIndex: string | number) => void
}>()
function setOffset(sid: string | number, axis: 'x' | 'y', event: Event) {
  const input = event.target as HTMLInputElement
  const point = props.style.value(sid) as PointF
  const previous = axis === 'x' ? point.x() : point.y()
  if (input.value === '' || !Number.isFinite(input.valueAsNumber)) { input.value = String(previous); return }
  const v = input.valueAsNumber
  props.style.setValue(sid, new PointF(axis === 'x' ? v : point.x(), axis === 'y' ? v : point.y()))
}
function measureOffset(above: boolean): string | number {
  const type = Number(props.style.value('measureNumberTextStyle')) as TextStyleType
  if (above) return textStyle(type)![TextStylePropertyType.Offset - 1].sid
  return type === TextStyleType.MEASURE_NUMBER_ALTERNATE ? 'measureNumberAlternatePosBelow' : 'measureNumberPosBelow'
}
function setMmRestOffset(axis: 'x' | 'y', event: Event) {
  const sid = props.style.value('mmRestRangeVPlacement') === 0 ? 'mmRestRangePosAbove' : 'mmRestRangePosBelow'
  setOffset(sid, axis, event)
}
useLanguage()
</script>

<template>
  <div class="sd-column" style="gap:12px">
    <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{ qtrc('editstyle', 'Measure numbers') }}</legend><div class="sd-column" style="gap:8px">
      <label class="sd-toggle"><input type="checkbox" role="switch" :checked="style.value('showMeasureNumber') === true" @change="style.setValue('showMeasureNumber',!style.value('showMeasureNumber'))"><span class="sd-toggle-track" aria-hidden="true"></span><span>{{ qtrc('editstyle','Show measure numbers') }}</span></label>
      <label class="sd-checkbox" :class="{disabled:!style.value('showMeasureNumber')}"><input type="checkbox" :disabled="!style.value('showMeasureNumber')" :checked="style.value('showMeasureNumberOne') === true" @change="style.setValue('showMeasureNumberOne',!style.value('showMeasureNumberOne'))"><span>{{ qtrc('notation/editstyle/voltas','Show initial measure number') }}</span></label>
      </div><div class="sd-column" style="gap:8px;margin-top:12px" :class="{disabled:!style.value('showMeasureNumber')}"><span class="sd-label">{{ qtrc('notation/editstyle/voltas', 'Text style') }}</span><div class="sd-row" style="gap:4px"><select class="sd-dropdown" style="min-width:192px" :disabled="!style.value('showMeasureNumber')" :value="style.value('measureNumberTextStyle')" @change="style.setValue('measureNumberTextStyle', Number(($event.target as HTMLSelectElement).value))"><option v-for="type in allTextStyles()" :key="type" :value="type">{{ TConv.userNameTextStyleType(type).translated() }}</option></select>
      <button type="button" class="sd-flat-button" :disabled="!style.value('showMeasureNumber')" @click="goToTextStylePage?.(allTextStyles().indexOf(Number(style.value('measureNumberTextStyle')) as TextStyleType))">{{ qtrc('notation', 'Edit text style') }}</button><button type="button" class="sd-flat-button icon-only" :disabled="!style.value('showMeasureNumber')" :aria-label="qtrc('global','Reset')" @click="style.resetValue?.('measureNumberTextStyle')"><span class="sd-icon">{{ String.fromCodePoint(ICON_CODES.UNDO) }}</span></button></div></div></fieldset>
      <fieldset class="sd-groupbox" style="min-width:500px" :class="{disabled:!style.value('showMeasureNumber')}" :disabled="!style.value('showMeasureNumber')"><legend>{{ qtrc('notation/editstyle/voltas','Frequency') }}</legend><div class="sd-column" style="gap:8px"><label class="sd-radio"><input type="radio" name="measure-frequency" :checked="style.value('measureNumberSystem')===true" @change="style.setValue('measureNumberSystem',true)"><span>{{ qtrc('notation/editstyle/voltas','Start of each system') }}</span></label><div class="sd-row" style="gap:12px"><label class="sd-radio"><input type="radio" name="measure-frequency" :checked="style.value('measureNumberSystem')===false" @change="style.setValue('measureNumberSystem',false)"><span>{{ qtrc('notation/editstyle/voltas','Every') }}</span></label><ChordNumber :style-model="style" id="measureNumberInterval" :label="qtrc('notation/editstyle/voltas','Every')" :min="1" :max="99" :step="1" :decimals="0" unit="" style="width:65px" /><span class="sd-label">{{ qtrc('notation/editstyle/voltas','measures') }}</span></div></div></fieldset>
      <fieldset class="sd-groupbox" style="min-width:500px" :class="{disabled:!style.value('showMeasureNumber')}" :disabled="!style.value('showMeasureNumber')"><legend>{{ qtrc('notation/editstyle/voltas','Position') }}</legend><div class="sd-column" style="gap:12px">
        <div class="sd-column" style="gap:8px"><span class="sd-label">{{ qtrc('notation/editstyle/voltas','Align') }}</span><div class="sd-column" style="gap:8px"><label v-for="option in [{label:'To the barline',value:true},{label:'To the measure',value:false}]" :key="String(option.value)" class="sd-radio"><input type="radio" name="measure-align" :checked="style.value('measureNumberAlignToBarline')===option.value" @change="style.setValue('measureNumberAlignToBarline',option.value)"><span>{{ qtrc('notation/editstyle/voltas',option.label) }}</span></label></div><span class="sd-label">{{ qtrc('notation/editstyle/voltas','Alignment') }}</span><div class="sd-flat-radio-group" role="radiogroup" :aria-label="qtrc('notation/editstyle/voltas','Alignment')" style="gap:4px"><button v-for="(icon,index) in [ICON_CODES.ALIGN_LEFT,ICON_CODES.ALIGN_HORIZONTAL_CENTER,ICON_CODES.ALIGN_RIGHT]" :key="index" type="button" role="radio" class="sd-flat-radio" style="width:30px;flex:none" :aria-checked="style.value('measureNumberHPlacement')===[0,2,1][index]" @click="style.setValue('measureNumberHPlacement',[0,2,1][index])"><span class="sd-icon">{{String.fromCodePoint(icon)}}</span></button></div></div>
        <div class="sd-column" style="gap:8px"><span class="sd-label">{{ qtrc('notation/editstyle/voltas','Show') }}</span><div class="sd-column" style="gap:8px"><label v-for="option in [{label:'Above system',value:0},{label:'Below system',value:1},{label:'At system marking positions',value:2},{label:'On all staves',value:3}]" :key="option.value" class="sd-radio"><input type="radio" name="measure-placement" :checked="style.value('measureNumberPlacementMode')===option.value" @change="style.setValue('measureNumberPlacementMode',option.value)"><span>{{qtrc('notation/editstyle/voltas',option.label)}}</span></label></div></div><div v-if="style.value('measureNumberPlacementMode')===3" class="sd-column" style="gap:8px"><span class="sd-label">{{qtrc('notation/editstyle/voltas','Position')}}</span><div class="sd-flat-radio-group" role="radiogroup" style="gap:4px"><button v-for="(label,index) in ['Above','Below']" :key="label" type="button" role="radio" class="sd-flat-radio" style="width:176px;flex:none" :aria-label="qtrc('notation/editstyle/voltas',label)" :aria-checked="style.value('measureNumberVPlacement')===index" @click="style.setValue('measureNumberVPlacement',index)">{{qtrc('notation/editstyle/voltas',label)}}</button></div></div>
        <div class="sd-column" style="gap:8px"><div v-for="above in [true,false]" :key="String(above)" class="sd-row" style="gap:6px"><span class="sd-label" style="width:156px">{{qtrc('notation/editstyle/voltas',above?'Offset when above staff:':'Offset when below staff:')}}</span><StyledXYControllerWithReset :style-model="style" :sid="measureOffset(above)" /></div></div></div></fieldset>
      <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{qtrc('notation/editstyle/voltas','Measure number range at multimeasure rests')}}</legend><div class="sd-column" style="gap:12px"><label class="sd-toggle"><input type="checkbox" role="switch" :checked="style.value('mmRestShowMeasureNumberRange') === true" @change="style.setValue('mmRestShowMeasureNumberRange',!style.value('mmRestShowMeasureNumberRange'))"><span class="sd-toggle-track" aria-hidden="true"></span><span>{{ qtrc('notation/editstyle/voltas','Show measure number ranges') }}</span></label><div class="sd-column" style="gap:8px" :class="{disabled:!style.value('mmRestShowMeasureNumberRange')}"><span class="sd-label">{{qtrc('notation/editstyle/voltas','Text style')}}</span><div class="sd-row" style="gap:4px"><select class="sd-dropdown" style="min-width:192px" :disabled="!style.value('mmRestShowMeasureNumberRange')" :value="style.value('mmRestRangeTextStyle')" @change="style.setValue('mmRestRangeTextStyle',Number(($event.target as HTMLSelectElement).value))"><option v-for="type in allTextStyles()" :key="type" :value="type">{{TConv.userNameTextStyleType(type).translated()}}</option></select><button type="button" class="sd-flat-button" :disabled="!style.value('mmRestShowMeasureNumberRange')" @click="goToTextStylePage?.(allTextStyles().indexOf(Number(style.value('mmRestRangeTextStyle')) as TextStyleType))">{{qtrc('notation','Edit text style')}}</button><button type="button" class="sd-flat-button icon-only" :disabled="!style.value('mmRestShowMeasureNumberRange')" :aria-label="qtrc('global','Reset')" @click="style.resetValue?.('mmRestRangeTextStyle')"><span class="sd-icon">{{String.fromCodePoint(ICON_CODES.UNDO)}}</span></button></div></div><div class="sd-column" style="gap:8px" :class="{disabled:!style.value('mmRestShowMeasureNumberRange')}"><span class="sd-label">{{qtrc('notation/editstyle/voltas','Bracket type')}}</span><div class="sd-flat-radio-group" style="width:362px;gap:4px"><button v-for="(label,index) in ['Brackets','Parentheses','None']" :key="label" type="button" role="radio" class="sd-flat-radio" :aria-label="qtrc('notation/editstyle/voltas',label)" :disabled="!style.value('mmRestShowMeasureNumberRange')" :aria-checked="style.value('mmRestRangeBracketType')===index" @click="style.setValue('mmRestRangeBracketType',index)">{{qtrc('notation/editstyle/voltas',label)}}</button></div></div><div class="sd-column" style="gap:8px" :class="{disabled:!style.value('mmRestShowMeasureNumberRange')}"><span class="sd-label">{{qtrc('notation/editstyle/voltas','Alignment')}}</span><div class="sd-flat-radio-group" style="gap:4px"><button v-for="(icon,index) in [ICON_CODES.ALIGN_LEFT,ICON_CODES.ALIGN_HORIZONTAL_CENTER,ICON_CODES.ALIGN_RIGHT]" :key="index" type="button" class="sd-flat-radio" style="width:30px;flex:none" :disabled="!style.value('mmRestShowMeasureNumberRange')" :aria-checked="style.value('mmRestRangeHPlacement')===[0,2,1][index]" @click="style.setValue('mmRestRangeHPlacement',[0,2,1][index])"><span class="sd-icon">{{String.fromCodePoint(icon)}}</span></button></div></div><div class="sd-column" style="gap:8px" :class="{disabled:!style.value('mmRestShowMeasureNumberRange')}"><span class="sd-label">{{qtrc('notation/editstyle/voltas','Position')}}</span><div class="sd-flat-radio-group" style="width:362px;gap:4px"><button v-for="(label,index) in ['Above','Below']" :key="label" type="button" role="radio" class="sd-flat-radio" :aria-label="qtrc('notation/editstyle/voltas',label)" :disabled="!style.value('mmRestShowMeasureNumberRange')" :aria-checked="style.value('mmRestRangeVPlacement')===index" @click="style.setValue('mmRestRangeVPlacement',index)">{{qtrc('notation/editstyle/voltas',label)}}</button></div></div><div class="sd-column" style="gap:8px" :class="{disabled:!style.value('mmRestShowMeasureNumberRange')}"><span class="sd-label">{{qtrc('notation/editstyle/voltas','Offset')}}</span><StyledXYControllerWithReset :style-model="style" :sid="style.value('mmRestRangeVPlacement')===0?'mmRestRangePosAbove':'mmRestRangePosBelow'" :disabled="!style.value('mmRestShowMeasureNumberRange')" /></div></div></fieldset>
  </div>
</template>
